data.styles:
/* GLOBAL STYLES */
* { margin: 0; padding: 0; box-sizing: border-box; }
body { font-family: 'Segoe UI', system-ui, -apple-system, sans-serif; color: var(--color-text); line-height: 1.6; background: var(--color-bg); overflow-wrap: break-word; }
a { color: var(--color-primary); text-decoration: none; transition: color 0.3s; }
a:hover { color: var(--color-primary-dark); }

/* NAVIGATION */
.main-nav { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; padding: 1rem 2rem; background: var(--color-bg-card); box-shadow: 0 2px 10px var(--shadow-color); position: sticky; top: 0; z-index: 100; }
.nav-logo { font-size: 1.5rem; font-weight: 700; color: var(--color-primary); }
.nav-links { display: flex; flex-wrap: wrap; gap: 2rem; list-style: none; }
.nav-links a { color: var(--color-text); font-weight: 500; }
.nav-links a:hover { color: var(--color-primary); }

/* HERO */
.hero { text-align: center; padding: 6rem 2rem; background: linear-gradient(135deg, var(--color-bg-card) 0%, var(--color-bg) 100%); }
.hero h1 { font-size: clamp(2rem, 5vw + 0.75rem, 3rem); margin-bottom: 1rem; color: var(--color-text); }
.hero p { font-size: 1.25rem; color: var(--color-text-muted); margin-bottom: 2rem; max-width: 600px; margin-left: auto; margin-right: auto; }

/* BUTTONS */
.btn { display: inline-block; padding: 0.75rem 1.5rem; border-radius: 0.5rem; font-weight: 600; transition: all 0.3s; }
.btn-primary { background: var(--color-primary); color: var(--color-on-primary); }
.btn-primary:hover { background: var(--color-primary-dark); color: var(--color-on-primary); }

/* FEATURES */
.features { padding: 5rem 2rem; max-width: 1200px; margin: 0 auto; }
.features h2 { text-align: center; font-size: 2rem; margin-bottom: 3rem; }
.features-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(300px, 100%), 1fr)); gap: 2rem; }
.feature-card { padding: 2rem; background: var(--color-bg-card); border-radius: 1rem; box-shadow: 0 4px 20px var(--shadow-color); transition: transform 0.3s; }
.feature-card:hover { transform: translateY(-5px); }
.feature-card h3 { color: var(--color-primary); margin-bottom: 0.5rem; }
.feature-card p { color: var(--color-text-muted); }

/* PAGE HEADER */
.page-header { text-align: center; padding: 4rem 2rem; background: var(--color-bg-card); }
.page-header h1 { font-size: clamp(1.75rem, 4vw + 1rem, 2.5rem); margin-bottom: 0.5rem; }
.page-header p { color: var(--color-text-muted); font-size: 1.1rem; }

/* SERVICES */
.services-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(300px, 100%), 1fr)); gap: 2rem; padding: 3rem 2rem; max-width: 1200px; margin: 0 auto; }
.service-card { padding: 2rem; background: var(--color-bg-card); border-radius: 0.5rem; border-left: 4px solid var(--color-primary); box-shadow: 0 2px 10px var(--shadow-color); }
.service-card h3 { color: var(--color-primary); margin-bottom: 0.5rem; }
.service-card p { color: var(--color-text-muted); }

/* CONTACT */
.contact-info { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(250px, 100%), 1fr)); gap: 2rem; padding: 3rem 2rem; max-width: 900px; margin: 0 auto; }
.contact-item { padding: 1.5rem; background: var(--color-bg-card); border-radius: 0.5rem; text-align: center; box-shadow: 0 2px 10px var(--shadow-color); }
.contact-item h3 { color: var(--color-primary); margin-bottom: 0.5rem; font-size: 0.9rem; text-transform: uppercase; }
.contact-item p { color: var(--color-text); }

/* ABOUT */
.about-content { padding: 3rem 2rem; max-width: 800px; margin: 0 auto; }
.about-content h2 { color: var(--color-primary); margin-bottom: 1rem; }
.about-content p { color: var(--color-text-muted); line-height: 1.8; }

/* FOOTER */
.main-footer { background: var(--color-bg-footer); color: var(--color-text-light); padding: 3rem 2rem 1rem; }
.footer-content { display: flex; justify-content: space-between; align-items: flex-start; max-width: 1200px; margin: 0 auto; flex-wrap: wrap; gap: 2rem; }
.footer-logo { font-size: 1.25rem; font-weight: 700; color: var(--color-primary); }
.footer-brand p { color: var(--color-footer-muted); margin-top: 0.5rem; font-size: 0.9rem; }
.footer-nav { display: flex; gap: 1.5rem; }
.footer-nav a { color: var(--color-footer-muted); font-size: 0.9rem; }
.footer-nav a:hover { color: var(--color-primary); }
.footer-bottom { text-align: center; padding-top: 2rem; margin-top: 2rem; border-top: 1px solid rgba(255,255,255,0.1); color: var(--color-footer-muted); font-size: 0.85rem; }

/* LANGUAGE SWITCH (a site in several languages) */
.footer-lang { display: flex; align-items: center; gap: 0.75rem; }
.lang-label { color: var(--color-footer-muted); font-size: 0.9rem; }
.lang-switch { display: flex; gap: 0.5rem; }
.lang-btn { color: var(--color-footer-muted); padding: 0.3rem 0.8rem; border-radius: 0.5rem; font-size: 0.85rem; border: 1px solid rgba(255,255,255,0.15); }
.lang-btn:hover { color: var(--color-primary); border-color: var(--color-primary); }

/* THEME SWITCH (a site with a dark theme) */
.theme-switch { display: inline-flex; align-items: center; gap: 0.4rem; padding: 0.4rem 0.9rem; border-radius: 20px; border: 1px solid var(--color-switch-border); background: transparent; color: var(--color-switch-text); font: inherit; font-size: 0.85rem; font-weight: 500; cursor: pointer; transition: all 0.3s ease; }
.theme-switch:hover { border-color: var(--color-primary); color: var(--color-primary); }

/* PHONE (a screen up to 40rem): the menu scrolls with the page, its links on a row of their own; less room around the content */
@media (max-width: 40rem) {
    .main-nav { position: static; padding: 0.75rem 1rem; gap: 0.5rem 1rem; }
    .nav-links { order: 1; width: 100%; gap: 0.25rem 1.5rem; }
    .hero { padding: 3.5rem 1rem; }
    .features { padding: 3rem 1rem; }
    .page-header { padding: 2.5rem 1rem; }
    .services-grid, .contact-info, .about-content { padding: 2rem 1rem; }
    .main-footer { padding: 2rem 1rem 1rem; }
}
